def first_touch(path, upper, lower, h):
    """path[0] is the entry close. Returns (label, days held)."""
    last = min(h, len(path) - 1)
    for d in range(1, last + 1):
        if path[d] <= lower:
            return (-1, d)
        if path[d] >= upper:
            return (1, d)
    return (0, last)

