import math

def triple_barrier_labels(prices, vol, k, h):
    out = []
    for t in range(len(prices) - h):
        if math.isnan(vol[t]):
            continue
        out.append(first_touch(prices[t:t + h + 1], prices[t] * (1 + k * vol[t]), prices[t] * (1 - k * vol[t]), h)[0])
    return out

